# Prompt Injection Defense: tiny safety gate for the running case.
request = {
    "action": "issue_refund",
    "has_user_confirmation": False,
    "contains_sensitive_data": True,
    "has_audit_log": True,
}

def safety_decision(req):
    if req["action"] == "issue_refund" and not req["has_user_confirmation"]:
        return "block"
    if req["contains_sensitive_data"] and not req["has_audit_log"]:
        return "block"
    return "allow"

print(safety_decision(request))
print("ask human" if safety_decision(request) == "block" else "continue")
